/**
 * Generates packages/sdk/src/abi/*.ts from the Foundry artifacts in contracts/out, as `as const` arrays so viem can
 * infer argument and return types.
 *
 *   pnpm sync-abi            # forge build, then write the files
 *   pnpm sync-abi --no-build # use the existing contracts/out
 *   pnpm sync-abi --check    # exit 1 if a generated file is out of date (for CI)
 */
import { execFileSync } from 'node:child_process';
import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const contractsDir = join(root, 'contracts');
const outDir = join(contractsDir, 'out');
const abiDir = join(root, 'packages', 'sdk', 'src', 'abi');

/** [source file name, contract name]. Interfaces cover what the SDK reads from contracts it does not deploy. */
const CONTRACTS: ReadonlyArray<readonly [string, string]> = [
  ['CanonicalPoolRegistry', 'CanonicalPoolRegistry'],
  ['FeeCommitHook', 'FeeCommitHook'],
  ['DemoSwapRouter', 'DemoSwapRouter'],
  ['DemoLaunchpad', 'DemoLaunchpad'],
  ['QuoteAwareFeeHook', 'QuoteAwareFeeHook'],
  ['V4Quoter', 'V4Quoter'],
  ['StateView', 'StateView'],
  ['IPoolManager', 'IPoolManager'],
];

const HEADER = '// Generated by scripts/sync-abi.ts from contracts/out. Do not edit.\n';

const args = new Set(process.argv.slice(2));
const check = args.has('--check');

if (!args.has('--no-build') && !check) {
  execFileSync('forge', ['build'], { cwd: contractsDir, stdio: 'inherit' });
}

const lowerFirst = (s: string) => s[0]!.toLowerCase() + s.slice(1);

const files = new Map<string, string>();
for (const [file, name] of CONTRACTS) {
  const artifact = join(outDir, `${file}.sol`, `${name}.json`);
  if (!existsSync(artifact)) throw new Error(`missing ${artifact}; run forge build in contracts/`);
  const { abi } = JSON.parse(readFileSync(artifact, 'utf8')) as { abi: unknown[] };
  files.set(`${name}.ts`, `${HEADER}export const ${lowerFirst(name)}Abi = ${JSON.stringify(abi, null, 2)} as const;\n`);
}
files.set(
  'index.ts',
  HEADER + CONTRACTS.map(([, name]) => `export { ${lowerFirst(name)}Abi } from './${name}.js';\n`).join(''),
);

let stale = 0;
for (const [name, content] of files) {
  const path = join(abiDir, name);
  const current = existsSync(path) ? readFileSync(path, 'utf8') : undefined;
  if (current === content) continue;
  if (check) {
    console.error(`out of date: packages/sdk/src/abi/${name}`);
    stale++;
  } else {
    writeFileSync(path, content);
    console.log(`wrote packages/sdk/src/abi/${name}`);
  }
}
if (check && stale > 0) process.exit(1);
